import pytest

from tapedeck.engine import tape


def minimal_tape():
    return {
        "session": {
            "sdk": "pytest-sdk",
            "captured_at": "2026-01-01T00:00:00Z",
            "duration_s": 0,
        },
        "timeline": [],
        "mocked_modules": {},
        "value_index": {},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": False,
        },
    }


def rich_tape():
    result = minimal_tape()
    result["timeline"] = [
        {
            "seq": 0,
            "t": 0,
            "dir": "in",
            "container": "package.Client",
            "method": "fetch",
            "args": {"id": 0, "enabled": False, "label": ""},
            "value_ref": "request-0",
        },
        {
            "seq": 1,
            "t": 0.25,
            "dir": "out",
            "container": "package.Client",
            "method": "fetch",
            "result_ref": "result-0",
        },
    ]
    result["mocked_modules"] = {
        "package.Client": {
            "methods": {
                "fetch": {"return_value": {"$ref": "result-0"}},
                "reset": {"return_value": None},
            }
        },
        "package.OtherClient": {
            "methods": {
                "fetch": {"return_value": False},
            }
        },
    }
    result["value_index"] = {
        "request-0": {"id": 0, "enabled": False, "label": ""},
        "result-0": {"items": [], "count": 0},
    }
    result["nested_schemas"] = {}
    result["hierarchical_bindings"] = {
        "package.Client_result": "package.Client",
    }
    return result


