class RecorderLike:
    def __init__(self):
        self.timeline = [
            {
                "seq": 0,
                "t": 0,
                "dir": "in",
                "container": "package.Client_result",
                "method": "fetch",
                "payload": {"empty": "", "zero": 0, "false": False},
            },
            {
                "seq": 1,
                "t": 1,
                "dir": "out",
                "container": "package.Client_result",
                "method": "fetch",
                "payload": None,
            },
        ]
        self.mocked_modules = {
            "package.Client_result": {
                "methods": {
                    "fetch": {"return_value": None},
                    "other": {"return_value": False},
                }
            },
            "package.Other": {
                "methods": {
                    "fetch": {"return_value": 0},
                }
            },
        }
        self.value_index = {
            "zero": 0,
            "false": False,
            "empty": "",
            "none": None,
        }
        self.nested_schemas = {}
        self.hierarchical_bindings = {
            "package.Client_result": "package.Client",
        }


def test_build_tape_preserves_session_and_recorder_content_without_aliasing():
    recorder = RecorderLike()
    session_meta = {
        "sdk": "pytest-sdk",
        "captured_at": "2026-01-01T00:00:00Z",
        "duration_s": 1,
        "custom": {"nested": "original"},
    }
    original_session = copy.deepcopy(session_meta)
    original_timeline = copy.deepcopy(recorder.timeline)
    original_modules = copy.deepcopy(recorder.mocked_modules)

    built = tape.build_tape(recorder, session_meta)

    assert isinstance(built, dict)
    assert set(tape.REQUIRED_KEYS).issubset(built)
    assert built["session"]["sdk"] == "pytest-sdk"
    assert built["session"]["custom"] == {"nested": "original"}
    assert built["timeline"] == recorder.timeline
    assert built["mocked_modules"] == recorder.mocked_modules
    assert built["value_index"] == recorder.value_index
    assert built["timeline"][0]["dir"] == "in"
    assert built["timeline"][1]["dir"] == "out"
    assert built["mocked_modules"]["package.Client_result"]["methods"]["other"][
        "return_value"
    ] is False
    assert built["hierarchical_bindings"]["package.Client_result"] == "package.Client"

    tape.validate_tape(built)

    session_meta["custom"]["nested"] = "changed"
    assert built["session"]["custom"]["nested"] == "original"

    built["session"]["custom"]["nested"] = "tape-only"
    assert session_meta["custom"]["nested"] == "changed"
    assert recorder.timeline == original_timeline
    assert recorder.mocked_modules == original_modules
    assert session_meta["sdk"] == original_session["sdk"]


