import json

import pytest

import tapedeck.engine.tape as tape


class _RecorderDouble:
    def __init__(self):
        self.timeline = [
            {
                "seq": 1,
                "t": 0.125,
                "dir": "in",
                "container": "sdk.Client",
                "method": "create",
            }
        ]
        self.mocked_modules = {
            "sdk.Client": {
                "methods": {
                    "create": {
                        "return_value": {"id": "client-1"},
                    }
                }
            }
        }
        self.value_index = {"client-1": {"id": "client-1"}}
        self.nested_schemas = {}
        self.hierarchical_bindings = {}

        # Common aliases for captured interactions used by recorder-style objects.
        self.interactions = self.timeline
        self.events = self.timeline
        self.records = self.timeline
        self.calls = self.timeline


def _valid_tape():
    return {
        "session": {
            "sdk": "example-sdk",
            "captured_at": "2026-10-02T12:00:00Z",
            "duration_s": 1.25,
        },
        "timeline": [
            {
                "seq": 1,
                "t": 0.0,
                "dir": "in",
                "container": "sdk.Client",
                "method": "create",
            }
        ],
        "mocked_modules": {
            "sdk.Client": {
                "methods": {
                    "create": {
                        "return_value": {"id": "created"},
                    }
                }
            }
        },
        "value_index": {"created": {"id": "created"}},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
    }


def test_build_tape_produces_required_top_level_shape():
    recorder = _RecorderDouble()
    session_meta = {
        "sdk": "build-sdk",
        "captured_at": "2026-10-02T01:02:03Z",
        "duration_s": 3.5,
    }

    result = tape.build_tape(recorder, session_meta)

    assert set(tape.REQUIRED_KEYS).issubset(result), (
        "The resulting tape contains session, timeline, mocked_modules, and metadata."
    )
    assert "value_index" in result, "The resulting tape contains value_index."
    assert result["metadata"]["capture_mode"] == "value_capture", (
        "metadata.capture_mode is value_capture."
    )
    assert result["metadata"]["prefer_return_value"] is True, (
        "metadata.prefer_return_value is true."
    )


