        assert tape.validate_tape(valid_tape) is None, (
            'A timeline entry dir is "in" or "out".'
        )

    for direction in ("inbound", "outbound", "", None):
        invalid_tape = _valid_tape()
        invalid_tape["timeline"][0]["dir"] = direction

