        [
            "sdk.Client_result.messages.create",
            "sdk.Client_result.files.list",
        ]
    )

    assert bindings == {"sdk.Client_result": "sdk.Client"}, (
        'The inferred bindings contain one "sdk.Client_result" to "sdk.Client" mapping.'
    )


