    )


def test_infer_bindings_finds_each_capitalized_result_prefix():
    bindings = tape.infer_hierarchical_bindings(
        ["sdk.Client_result.api.Service_result.call"]
    )

    assert bindings["sdk.Client_result"] == "sdk.Client", (
        '"sdk.Client_result" maps to "sdk.Client".'
    )
    assert (
        bindings["sdk.Client_result.api.Service_result"]
        == "sdk.Client_result.api.Service"
    ), (
        '"sdk.Client_result.api.Service_result" maps to '
