from tapedeck.engine import serialize


def _contains_fragment(value, fragment):
    if isinstance(value, str):
        return fragment in value
    if isinstance(value, dict):
        return any(_contains_fragment(item, fragment) for item in value.values())
    if isinstance(value, (list, tuple)):
        return any(_contains_fragment(item, fragment) for item in value)
    return False


