import json

import pytest

import tapedeck.engine.tape as tape


class _RecorderStub:
    """Minimal recorder-shaped object containing captured tape data."""

    def __init__(
        self,
        *,
        timeline=None,
        mocked_modules=None,
        value_index=None,
        metadata=None,
        nested_schemas=None,
        hierarchical_bindings=None,
    ):
        self.timeline = [] if timeline is None else timeline
        self.mocked_modules = {} if mocked_modules is None else mocked_modules
        self.value_index = {} if value_index is None else value_index
        self.metadata = (
            {
                "capture_mode": "value_capture",
                "prefer_return_value": True,
            }
            if metadata is None
            else metadata
        )
        self.capture_mode = self.metadata["capture_mode"]
        self.prefer_return_value = self.metadata["prefer_return_value"]
        self.nested_schemas = {} if nested_schemas is None else nested_schemas
        self.hierarchical_bindings = (
            {} if hierarchical_bindings is None else hierarchical_bindings
        )


def _valid_tape():
    return {
        "session": {
            "sdk": "example-sdk",
            "captured_at": "2026-01-02T03:04:05Z",
            "duration_s": 1.25,
        },
        "timeline": [],
        "mocked_modules": {},
        "value_index": {},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
    }


def test_build_tape_produces_required_top_level_shape():
    recorder = _RecorderStub(
        value_index={"value-1": {"kind": "str", "value": "captured"}},
    )
    session_meta = {
        "sdk": "unit-test-sdk",
        "captured_at": "2026-01-02T03:04:05Z",
        "duration_s": 2.5,
    }

    built = tape.build_tape(recorder, session_meta)

    assert set(tape.REQUIRED_KEYS).issubset(built), (
        "the returned tape contains session, timeline, mocked_modules, and metadata"
    )
    assert built["value_index"] == {"value-1": {"kind": "str", "value": "captured"}}, (
        "the returned tape contains value_index"
    )


def test_build_tape_preserves_session_metadata():
    session_meta = {
        "sdk": "sdk-under-test",
        "captured_at": "2026-05-06T07:08:09Z",
