    )


def test_build_tape_emits_timeline_entry_shape():
    captured_timeline = [
        {"seq": 7, "t": 0.125, "dir": "in", "payload": {"request": "hello"}},
        {"seq": 8, "t": 0.250, "dir": "out", "payload": {"response": "world"}},
    ]

    built = tape.build_tape(
        _RecorderStub(timeline=captured_timeline),
        _valid_tape()["session"],
    )

    assert built["timeline"] == captured_timeline
    assert all({"seq", "t", "dir"}.issubset(entry) for entry in built["timeline"]), (
        "each timeline entry contains seq, t, and dir"
    )
    assert {entry["dir"] for entry in built["timeline"]} == {"in", "out"}, (
        "each timeline entry dir is in or out"
    )


def test_build_tape_emits_mocked_module_method_shape():
    mocked_modules = {
        "package.Client": {
            "methods": {
                "request": {"return_value": {"status": 200}},
                "close": {"return_value": None},
            }
        }
    }

    built = tape.build_tape(
        _RecorderStub(mocked_modules=mocked_modules),
        _valid_tape()["session"],
    )

    assert built["mocked_modules"] == mocked_modules
    assert all(
        isinstance(container_config, dict) and "methods" in container_config
        for container_config in built["mocked_modules"].values()
    ), "tape.mocked_modules maps each container to an object containing methods"
    assert all(
        isinstance(method_name, str)
        for container_config in built["mocked_modules"].values()
        for method_name in container_config["methods"]
    ), "each methods object maps method names to configurations"


