import pytest

from tapedeck.engine import serialize


def test_redactor_collects_secret_environment_values_and_explicit_extras():
    token = "tok_abc123"
    password = "p@ss.word"
    extra_secret = "extra-secret-value"

    redactor = serialize.Redactor.from_environ(
        {
            "SERVICE_TOKEN": token,
            "database_password": password,
            "PUBLIC_NAME": "ordinary-value",
        },
        extra=[extra_secret],
    )

    text = (
        "token=%s password=%s extra=%s public=ordinary-value"
        % (token, password, extra_secret)
    )
    scrubbed = redactor.scrub(text)

    assert token not in scrubbed
    assert password not in scrubbed
    assert extra_secret not in scrubbed
    assert "ordinary-value" in scrubbed
    assert redactor.scrub("a completely harmless string") == "a completely harmless string"


def test_redactor_treats_secret_values_as_literal_substrings():
    secret = "literal.[secret](value)?"
    redactor = serialize.Redactor.from_environ({}, extra=[secret])

    scrubbed = redactor.scrub("before %s after" % secret)

    assert secret not in scrubbed
    assert scrubbed.startswith("before ")
    assert scrubbed.endswith(" after")


def test_snapshot_recursively_removes_secret_looking_dictionary_keys():
    redactor = serialize.Redactor.from_environ({}, extra=["known-secret"])
    schemas = {}

    result = serialize.snapshot(
        {
            "visible": "ok",
            "Authorization": "Bearer known-secret",
            "nested": {
                "api_key": "known-secret",
                "refreshToken": "known-secret",
                "still_visible": "known-secret appears here",
            },
            "items": [
                {"password_hint": "known-secret"},
                {"safe": "known-secret"},
            ],
        },
        redactor,
        schemas,
    )

    assert result["visible"] == "ok"
    assert "Authorization" not in result
    assert "api_key" not in result["nested"]
    assert "refreshToken" not in result["nested"]
    assert "password_hint" not in result["items"][0]
    assert result["items"][1]["safe"] != "known-secret"
    assert "known-secret" not in result["nested"]["still_visible"]
    assert schemas == {}


def test_snapshot_preserves_json_primitives_and_converts_tuples_to_lists():
    redactor = serialize.Redactor.from_environ({}, extra=["super-secret"])
    schemas = {}

    result = serialize.snapshot(
        {
            "none": None,
            "bool": True,
            "number": 7,
            "decimal": 1.5,
            "tuple": ("safe", "contains super-secret"),
            "list": [False, {"message": "super-secret"}],
        },
        redactor,
        schemas,
    )

    assert result["none"] is None
    assert result["bool"] is True
    assert result["number"] == 7
    assert result["decimal"] == 1.5
    assert isinstance(result["tuple"], list)
    assert result["tuple"][0] == "safe"
    assert "super-secret" not in result["tuple"][1]
    assert result["list"][0] is False
    assert "super-secret" not in result["list"][1]["message"]
    assert schemas == {}


def test_snapshot_serializes_public_object_attributes_and_records_schema():
    class InventoryItem:
        def __init__(self):
            self.name = "widget"
            self.quantity = 3
            self.active = True
            self.tags = ["sale", "new"]
            self._private_note = "must not be serialized"

    redactor = serialize.Redactor.from_environ({})
    schemas = {}

    result = serialize.snapshot(InventoryItem(), redactor, schemas)

    assert result == {
        "__type__": "InventoryItem",
        "name": "widget",
        "quantity": 3,
        "active": True,
        "tags": ["sale", "new"],
    }
    assert schemas == {
        "InventoryItem": {
            "name": "str",
            "quantity": "int",
            "active": "bool",
            "tags": "list",
        }
    }


def test_snapshot_redacts_known_secret_values_inside_object_attributes():
    class Connection:
        def __init__(self):
            self.description = "connecting with token abc-secret-token now"
            self.headers = {
                "X-Trace": "token abc-secret-token",
                "apiKey": "abc-secret-token",
            }

    redactor = serialize.Redactor.from_environ({}, extra=["abc-secret-token"])
    schemas = {}

    result = serialize.snapshot(Connection(), redactor, schemas)

    assert result["__type__"] == "Connection"
    assert "abc-secret-token" not in result["description"]
    assert "abc-secret-token" not in result["headers"]["X-Trace"]
    assert "apiKey" not in result["headers"]
    assert schemas["Connection"] == {
        "description": "str",
        "headers": "dict",
    }

import pytest

from tapedeck.engine import serialize


def test_scalar_values_remain_json_safe():
    redactor = serialize.Redactor.from_environ({})
    schemas = {}

    values = [None, True, False, 0, -17, 3.25, "ordinary text"]
    for value in values:
        result = serialize.snapshot(value, redactor, schemas)
        assert result == value
        assert type(result) is type(value)

    assert schemas == {}


