import json

import pytest

from tapedeck.engine import tape as tape_module


class _Recorder:
    """Small duck-typed recorder containing the data build_tape consumes."""

    def __init__(
        self,
        timeline=None,
        mocked_modules=None,
        value_index=None,
        nested_schemas=None,
        hierarchical_bindings=None,
    ):
        self.timeline = [] if timeline is None else timeline
        self.mocked_modules = {} if mocked_modules is None else mocked_modules
        self.value_index = {} if value_index is None else value_index
        self.nested_schemas = {} if nested_schemas is None else nested_schemas
        self.hierarchical_bindings = (
            {} if hierarchical_bindings is None else hierarchical_bindings
        )

        # Common aliases/accessors keep this recorder useful for implementations
        # that expose captured data through methods rather than direct attributes.
        self.events = self.timeline
        self.recorded_events = self.timeline
        self.modules = self.mocked_modules
        self.values = self.value_index

    def get_timeline(self):
        return self.timeline

    def get_mocked_modules(self):
        return self.mocked_modules

    def get_value_index(self):
        return self.value_index

    def get_nested_schemas(self):
        return self.nested_schemas

    def get_hierarchical_bindings(self):
        return self.hierarchical_bindings

    def to_dict(self):
        return {
            "timeline": self.timeline,
            "mocked_modules": self.mocked_modules,
            "value_index": self.value_index,
            "nested_schemas": self.nested_schemas,
            "hierarchical_bindings": self.hierarchical_bindings,
        }


