import json

import pytest

from tapedeck.engine import tape


def make_valid_tape():
    return {
        "session": {
            "sdk": "example-sdk",
            "captured_at": "2026-01-02T03:04:05Z",
            "duration_s": 1.25,
        },
        "timeline": [
            {
                "seq": 0,
                "t": 0.0,
                "dir": "in",
                "container": "example.client",
                "method": "send",
            },
            {
                "seq": 1,
                "t": 0.1,
                "dir": "out",
                "container": "example.client",
                "method": "send",
            },
        ],
        "mocked_modules": {
            "example.client": {
                "methods": {
                    "send": {"return_value": {"ok": True}},
                }
            }
        },
        "value_index": {"value-1": {"ok": True}},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
    }


def test_required_keys_are_the_documented_top_level_requirements():
    assert tape.REQUIRED_KEYS == (
        "session",
        "timeline",
