def test_build_tape_collects_recorder_data_metadata_and_optional_schema_data():
    class RecorderDouble:
        timeline = [
            {
                "seq": 0,
                "t": 0.0,
                "dir": "in",
                "container": "acme.client.Widget_result",
                "method": "send",
            }
        ]
        mocked_modules = {
            "acme.client.Widget_result": {
                "methods": {
                    "send": {"return_value": "sent"},
                }
            }
        }
        value_index = {"return-1": "sent"}
        capture_mode = "value_capture"
        prefer_return_value = True
        nested_schemas = {
            "acme.client.Widget_result": {
                "type": "object",
                "properties": {"id": {"type": "integer"}},
            }
        }

    session_meta = {
        "sdk": "acme",
        "captured_at": "2026-01-02T03:04:05Z",
        "duration_s": 0.5,
    }

    built = tape.build_tape(RecorderDouble(), session_meta)

    assert built["session"] == session_meta
    assert built["timeline"] == RecorderDouble.timeline
    assert built["mocked_modules"] == RecorderDouble.mocked_modules
    assert built["value_index"] == RecorderDouble.value_index
    assert built["metadata"] == {
        "capture_mode": "value_capture",
        "prefer_return_value": True,
    }
    assert built["nested_schemas"] == RecorderDouble.nested_schemas
    assert built["hierarchical_bindings"] == {
        "acme.client.Widget_result": "acme.client.Widget"
    }
    assert tape.validate_tape(built) is None

