import pytest

import tapedeck.engine.serialize as serialize


def test_redactor_collects_only_secret_named_environment_values_and_extras():
    redactor = serialize.Redactor.from_environ(
        {
            "DATABASE_PASSWORD": "db-password-123",
            "SERVICE_TOKEN": "service-token-456",
            "PUBLIC_SETTING": "ordinary-public-value",
        },
        extra=("manually-supplied-secret",),
    )

    text = (
        "before db-password-123 / service-token-456 / "
        "manually-supplied-secret after"
    )
    scrubbed = redactor.scrub(text)

    assert "db-password-123" not in scrubbed
    assert "service-token-456" not in scrubbed
    assert "manually-supplied-secret" not in scrubbed
    assert scrubbed.startswith("before ")
    assert scrubbed.endswith(" after")
    assert redactor.scrub("ordinary-public-value") == "ordinary-public-value"
    assert redactor.scrub("a completely harmless string") == "a completely harmless string"


def test_redactor_handles_case_insensitive_secret_key_names_and_empty_values():
    redactor = serialize.Redactor.from_environ(
        {
            "Api_Key": "api-secret",
            "AUTHORIZATION": "authorization-secret",
            "refreshToken": "refresh-secret",
            "EMPTY_TOKEN": "",
        }
    )

    scrubbed = redactor.scrub(
        "api-secret authorization-secret refresh-secret ordinary text"
    )

    assert "api-secret" not in scrubbed
    assert "authorization-secret" not in scrubbed
    assert "refresh-secret" not in scrubbed
    assert "ordinary text" in scrubbed
    assert redactor.scrub("text unaffected by an empty secret") == (
        "text unaffected by an empty secret"
    )


def test_snapshot_recurses_through_json_containers_and_redacts_string_values():
