def test_snapshot_object_uses_public_attributes_and_records_schema():
    class Address:
        def __init__(self):
            self.city = "Paris"
            self.zip_code = 75000
            self._cache = "private implementation detail"

    class Customer:
        def __init__(self):
            self.name = "Ada"
            self.active = True
            self.address = Address()
            self.note = "contains customer-secret"
            self._internal = "not public"

    redactor = serialize.Redactor.from_environ(
