        "zip_code": 75000,
    }
    assert "_cache" not in result["address"]

    assert schemas == {
        "Customer": {
            "name": "str",
            "active": "bool",
            "address": "Address",
            "note": "str",
        },
        "Address": {
            "city": "str",
            "zip_code": "int",
        },
    }


