import json

import pytest

import tapedeck.engine.serialize as serialize


def _redactor(*extra):
    return serialize.Redactor.from_environ({}, extra=extra)


def _assert_secret_absent(secret, value):
    encoded = json.dumps(value, sort_keys=True)
    assert secret not in encoded


def test_from_environ_collects_only_secret_named_values_and_extra_values():
    redactor = serialize.Redactor.from_environ(
        {
            "API_KEY": "api-secret",
            "apiKey": "camel-secret",
            "PASSWORD": "password-secret",
            "authorization_header": "auth-secret",
            "MY_TOKEN_VALUE": "token-secret",
            "REFRESH_TOKEN": "refresh-secret",
            "DATABASE_URL": "ordinary-environment-value",
            "EMPTY_SECRET": "",
        },
        extra=("extra-secret", "", "api-secret"),
    )

    text = (
        "api-secret camel-secret password-secret auth-secret "
        "token-secret refresh-secret extra-secret ordinary-environment-value"
    )
    scrubbed = redactor.scrub(text)

    for secret in (
        "api-secret",
        "camel-secret",
        "password-secret",
        "auth-secret",
        "token-secret",
        "refresh-secret",
        "extra-secret",
    ):
        assert secret not in scrubbed

    assert "ordinary-environment-value" in scrubbed
    assert redactor.scrub("unchanged text") == "unchanged text"
    assert redactor.scrub("ordinary-environment-value") == "ordinary-environment-value"


def test_scrub_redacts_embedded_repeated_and_regex_special_secrets_literally():
    secret = r"p@ss.$*[]\value"
    redactor = _redactor(secret)

    text = (
        f"https://user:{secret}@example.test/path?api_key={secret}; "
        f"Bearer {secret}; repeated={secret}"
    )
    scrubbed = redactor.scrub(text)

    assert secret not in scrubbed
    assert scrubbed.startswith("https://user:")
    assert "@example.test/path?api_key=" in scrubbed
    assert "; Bearer " in scrubbed
    assert "; repeated=" in scrubbed
    assert redactor.scrub(f"before {secret} after") != f"before {secret} after"


def test_scrub_is_value_case_sensitive_and_handles_overlapping_secrets():
    redactor = _redactor("abc", "abcdef", "CaseSensitiveSecret")

    scrubbed = redactor.scrub("prefix abcdef suffix")
    assert "abcdef" not in scrubbed
    assert "def" not in scrubbed
    assert scrubbed.startswith("prefix ")
    assert scrubbed.endswith(" suffix")

    assert redactor.scrub("casesensitivesecret") == "casesensitivesecret"
    assert "CaseSensitiveSecret" not in redactor.scrub("CaseSensitiveSecret")


def test_snapshot_primitives_are_preserved_scrubbed_and_do_not_create_schemas():
    secret = "primitive-secret"
    redactor = _redactor(secret)
    schemas = {}

    assert serialize.snapshot(None, redactor, schemas) is None
    assert serialize.snapshot(True, redactor, schemas) is True
    assert serialize.snapshot(False, redactor, schemas) is False
    assert serialize.snapshot(42, redactor, schemas) == 42
    assert serialize.snapshot(-3.5, redactor, schemas) == -3.5
    assert serialize.snapshot("", redactor, schemas) == ""
    assert serialize.snapshot("snowman: ☃", redactor, schemas) == "snowman: ☃"

    value = serialize.snapshot(f"Bearer {secret}", redactor, schemas)
    assert secret not in value
    assert value.startswith("Bearer ")
    assert schemas == {}


def test_snapshot_dicts_recurse_and_drop_secret_looking_keys_at_every_level():
    secret = "dict-secret"
    redactor = _redactor(secret)
    schemas = {}

    value = {
        "safe": f"header Bearer {secret}",
        "password": "must-not-appear",
        "apiKey": "must-not-appear",
        "client_secret_hint": {"nested": "must-not-appear"},
        "nested": {
            "refresh_token_expiry": "must-not-appear",
            "safe_nested": f"url=https://x:{secret}@host",
        },
        "items": [f"one-{secret}", {"authorization": "must-not-appear"}],
    }

    result = serialize.snapshot(value, redactor, schemas)

    assert set(result) == {"safe", "nested", "items"}
    assert set(result["nested"]) == {"safe_nested"}
    assert result["items"][1] == {}
    assert secret not in result["safe"]
    assert secret not in result["nested"]["safe_nested"]
    assert secret not in result["items"][0]
    assert schemas == {}

    encoded = json.dumps(result, sort_keys=True)
    assert "must-not-appear" not in encoded
    assert secret not in encoded


def test_snapshot_lists_and_tuples_are_json_safe_and_preserve_order():
    secret = "collection-secret"
    redactor = _redactor(secret)
    schemas = {}

    result = serialize.snapshot(
        ["first", (2, f"token={secret}"), [], {"safe": secret}],
        redactor,
        schemas,
    )

    assert result[0] == "first"
    assert result[1][0] == 2
    assert isinstance(result[1], list)
    assert result[1][1] != f"token={secret}"
    assert result[2] == []
    assert result[3]["safe"] != secret
    _assert_secret_absent(secret, result)
    assert schemas == {}


def test_snapshot_object_shape_filters_private_and_secret_attributes_and_collects_schema():
    secret = "object-secret"

    class Child:
        def __init__(self):
            self.name = f"child-{secret}"

    class Example:
        def __init__(self):
            self.name = f"Bearer {secret}"
            self.count = 3
            self.child = Child()
            self.values = [1, 2]
            self.nothing = None
            self._private = f"private-{secret}"
            self.password = f"password-{secret}"
            self.refresh_token_expiry = f"refresh-{secret}"

    redactor = _redactor(secret)
    schemas = {}
    result = serialize.snapshot(Example(), redactor, schemas)

    assert result["__type__"] == "Example"
    assert set(result) == {"__type__", "name", "count", "child", "values", "nothing"}
    assert secret not in result["name"]
    assert result["count"] == 3
    assert result["child"]["__type__"] == "Child"
    assert secret not in result["child"]["name"]

    assert schemas["Example"] == {
        "name": "str",
        "count": "int",
        "child": "Child",
        "values": "list",
        "nothing": "NoneType",
    }
    assert schemas["Child"] == {"name": "str"}

