def test_snapshot_result_and_schema_are_json_serializable_without_secret_leaks():
    secret_one = "first-secret"
    secret_two = "second.$secret"

    class Nested:
        def __init__(self):
            self.endpoint = f"https://u:{secret_one}@host/?q={secret_two}"
            self.authorization = f"Bearer {secret_one}"

    class Root:
        def __init__(self):
            self.direct = secret_one
            self.items = [
                secret_two,
                {"safe": f"Bearer {secret_one}", "token_value": secret_two},
                Nested(),
            ]
            self._private = secret_two

    schemas = {}
