    assert secret_one not in encoded
    assert secret_two not in encoded
    assert result["items"][1] == {"safe": result["items"][1]["safe"]}
    assert result["items"][2]["__type__"] == "Nested"
    assert "authorization" not in result["items"][2]
    assert schemas["Root"]["items"] == "list"
    assert schemas["Nested"] == {"endpoint": "str"}

import pytest

import tapedeck.engine.serialize as serialize


def _redactor_with_secret(secret):
    return serialize.Redactor.from_environ({}, extra=(secret,))


def _all_strings(value):
    if isinstance(value, str):
        yield value
    elif isinstance(value, dict):
        for item in value.values():
            yield from _all_strings(item)
    elif isinstance(value, list):
        for item in value:
            yield from _all_strings(item)


def test_snapshot_json_primitives():
    redactor = serialize.Redactor.from_environ({})
    schemas = {}

    values = [None, True, False, 0, -17, 3.25, "ordinary text"]
    snapshots = [serialize.snapshot(value, redactor, schemas) for value in values]

    assert snapshots == values


def test_secret_key_pattern_is_case_insensitive():
