    assert result == {
        "outer": {
            "visible": "one",
            "items": [
                {"safe": "two"},
                {"deep": {"still_here": "three"}},
            ],
        },
        "ordinary": "four",
    }


def test_environ_secret_values_are_scrubbed():
    credential = "credential-value-123"
    redactor = serialize.Redactor.from_environ({"SERVICE_TOKEN": credential})

    before = redactor.scrub(f"{credential} follows ordinary text")
    between = redactor.scrub(f"before {credential} after")
    after = redactor.scrub(f"ordinary text precedes {credential}")

    assert credential not in before
    assert credential not in between
    assert credential not in after
    assert "ordinary text" in before
    assert "before " in between
    assert " after" in between
    assert "ordinary text precedes " in after


