    result = redactor.scrub(f"{credential}|{credential}|{credential}")

    assert credential not in result
    assert result.count("|") == 2


def test_snapshot_scrubs_string_values_at_any_depth():
    credential = "nested-value-secret"

    class Holder:
        def __init__(self):
            self.description = f"object contains {credential}"

    value = {
        "dictionary": {"message": f"dictionary contains {credential}"},
        "list": [f"list contains {credential}", {"other": f"again {credential}"}],
        "object": Holder(),
    }

    result = serialize.snapshot(value, _redactor_with_secret(credential), {})

    assert result["dictionary"]["message"] != value["dictionary"]["message"]
    assert result["list"][0] != value["list"][0]
    assert result["object"]["description"] != value["object"].description
    assert all(credential not in text for text in _all_strings(result))


