def test_redaction_applies_before_tape_output():
    credential = "never-write-this-credential"
    value = {
        "outer": [
            {
                "authorization_header": credential,
                "message": f"embedded credential: {credential}",
            },
            {"nested": {"refresh_token": credential, "safe": "retained"}},
        ]
    }

    result = serialize.snapshot(value, _redactor_with_secret(credential), {})

    assert result == {
        "outer": [
            {"message": result["outer"][0]["message"]},
            {"nested": {"safe": "retained"}},
        ]
    }
    assert credential not in result["outer"][0]["message"]
    assert all(credential not in text for text in _all_strings(result))
    assert "authorization_header" not in result["outer"][0]
    assert "refresh_token" not in result["outer"][1]["nested"]

