class _RecorderLike:
    def __init__(self):
        self.timeline = [
            {
                "seq": 0,
                "t": 0.0,
                "dir": "in",
                "container": "example.Client",
                "method": "create",
                "args": [],
                "kwargs": {},
            },
            {
                "seq": 1,
                "t": 0.01,
                "dir": "out",
                "container": "example.Client_result",
                "value": {"id": "client-1"},
            },
        ]
        self.mocked_modules = {
            "example.Client": {
                "methods": {
                    "create": {
                        "return_type": "example.Client_result",
                    }
                }
            },
            "example.Client_result": {
                "methods": {
                    "close": {},
                }
            },
        }
        self.value_index = {
            "value-1": {"kind": "dict", "value": {"id": "client-1"}}
        }
        self.nested_schemas = {
            "example.Client_result": {
                "fields": {"id": {"type": "string"}}
            }
        }
        self.metadata = {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        }

        # Common recorder aliases/configuration fields are intentionally kept
        # consistent with the documented tape metadata.
        self.events = self.timeline
        self._timeline = self.timeline
        self._mocked_modules = self.mocked_modules
        self._value_index = self.value_index
        self._nested_schemas = self.nested_schemas
        self.capture_mode = "value_capture"
