import json

import pytest

from tapedeck.engine import tape


class _CallableList(list):
    def __call__(self):
        return self


class _CallableDict(dict):
    def __call__(self):
        return self


class RecorderStub:
    def __init__(self, timeline, mocked_modules):
        self.timeline = _CallableList(timeline)
        self.mocked_modules = _CallableDict(mocked_modules)
        self.value_index = _CallableDict()
        self.nested_schemas = _CallableDict()

    def __getattr__(self, name):
        aliases = {
            "get_timeline": self.timeline,
            "get_mocked_modules": self.mocked_modules,
            "get_value_index": self.value_index,
            "get_nested_schemas": self.nested_schemas,
            "_timeline": self.timeline,
            "_mocked_modules": self.mocked_modules,
            "_value_index": self.value_index,
            "_nested_schemas": self.nested_schemas,
        }
        if name in aliases:
            return aliases[name]
        raise AttributeError(name)


def _valid_tape(direction="in"):
