from tapedeck.engine import serialize


def test_redactor_collects_secret_named_environment_values_and_extra_iterables():
    env_secret = "env-credential-123"
    extra_secret = "manually-supplied-secret"
    redactor = serialize.Redactor.from_environ(
        {
            "SERVICE_TOKEN": env_secret,
            "DISPLAY_NAME": "public-name",
            "EMPTY_API_KEY": "",
        },
        extra=(value for value in [extra_secret]),
    )

    original = (
        f"before {env_secret} middle {extra_secret} "
        "after public-name"
    )
    scrubbed = redactor.scrub(original)

    assert env_secret not in scrubbed
    assert extra_secret not in scrubbed
    assert scrubbed.startswith("before ")
    assert scrubbed.endswith("after public-name")
    assert redactor.scrub("plain text") == "plain text"
    assert redactor.scrub("public-name") == "public-name"


def test_snapshot_recursively_drops_secret_keys_and_scrubs_secret_values():
    env_secret = "environment-secret-value"
    extra_secret = "extra-secret-value"
    redactor = serialize.Redactor.from_environ(
        {"MY_API_KEY": env_secret},
        extra=[extra_secret],
    )
    schemas = {}
    payload = {
        "visible": f"Bearer {env_secret}",
        "nested": {
            "refresh_token": "must-be-removed",
            "safe_text": f"prefix {extra_secret} suffix",
        },
        "items": [
            env_secret,
            {
                "password_hint": "must-be-removed-too",
                "name": "ordinary",
            },
        ],
    }

    result = serialize.snapshot(payload, redactor, schemas)

    assert "refresh_token" not in result["nested"]
    assert "password_hint" not in result["items"][1]
    assert result["items"][1] == {"name": "ordinary"}

    assert env_secret not in repr(result)
    assert extra_secret not in repr(result)
    assert result["visible"].startswith("Bearer ")
    assert result["nested"]["safe_text"].startswith("prefix ")
    assert result["nested"]["safe_text"].endswith(" suffix")

    # Snapshotting must not destructively redact or remove source data.
    assert payload["nested"]["refresh_token"] == "must-be-removed"
    assert payload["items"][1]["password_hint"] == "must-be-removed-too"


