import pytest

import tapedeck.engine.serialize as serialize


def redactor(*extras, environ=None):
    return serialize.Redactor.from_environ(environ or {}, extras)


def assert_secret_absent(value, secret):
    if isinstance(value, str):
        assert secret not in value
    elif isinstance(value, list):
        for item in value:
            assert_secret_absent(item, secret)
    elif isinstance(value, dict):
        for key, item in value.items():
            assert secret not in str(key)
            assert_secret_absent(item, secret)


@pytest.mark.parametrize(
