        "client_credential",
        "refresh_token",
        "MiXeD_ToKeN_Value",
    ],
)
def test_secret_key_regex_matches_every_documented_fragment_case_insensitively(key):
    assert serialize.SECRET_KEY_RE.search(key)


def test_secret_key_regex_does_not_match_unrelated_key():
    assert serialize.SECRET_KEY_RE.search("username") is None


def test_redactor_collects_only_values_from_secret_environment_keys():
    value = redactor(environ={"API_TOKEN": "token-value", "USERNAME": "alice"})

    assert "token-value" not in value.scrub("token-value")
