def test_snapshot_preserves_json_scalars_and_scrubs_strings():
    schemas = {}
    value = redactor("top-level-secret")

    assert serialize.snapshot(None, value, schemas) is None
    assert serialize.snapshot(True, value, schemas) is True
    assert serialize.snapshot(False, value, schemas) is False
    assert type(serialize.snapshot(True, value, schemas)) is bool
    assert serialize.snapshot(42, value, schemas) == 42
    assert serialize.snapshot(0, value, schemas) == 0
    assert serialize.snapshot(-1, value, schemas) == -1
    assert serialize.snapshot(3.5, value, schemas) == 3.5
    assert serialize.snapshot("", value, schemas) == ""
    assert serialize.snapshot('{"__type__":"not-an-object"}', value, schemas) == (
        '{"__type__":"not-an-object"}'
    )

    result = serialize.snapshot("before top-level-secret after", value, schemas)
    assert "top-level-secret" not in result
    assert "before " in result
    assert " after" in result


