def test_snapshot_depth_is_propagated_from_supplied_starting_depth(monkeypatch):
    original_snapshot = serialize.snapshot
    observed_depths = []

    def recording_snapshot(value, redactor_value, schemas, depth=0):
        observed_depths.append(depth)
        return original_snapshot(value, redactor_value, schemas, depth)

    monkeypatch.setattr(serialize, "snapshot", recording_snapshot)

    original_snapshot({"outer": [{"inner": "value"}]}, redactor(), {}, depth=7)

    assert 8 in observed_depths
    assert 9 in observed_depths


def test_snapshot_supported_output_is_json_safe_without_runtime_instances():
    class PublicObject:
        def __init__(self):
            self.name = "alice"
            self.values = [None, True, 3.5, {"count": 2}]

    result = serialize.snapshot(
        {
            "null": None,
            "boolean": False,
            "number": 7,
            "text": "hello",
            "list": [1, "two"],
            "object": PublicObject(),
        },
        redactor(),
        {},
    )

    def assert_json_safe(value):
        assert value is None or type(value) in (bool, int, float, str, list, dict)
        if isinstance(value, list):
            for item in value:
                assert_json_safe(item)
        elif isinstance(value, dict):
            for key, item in value.items():
                assert type(key) is str
                assert_json_safe(item)

    assert_json_safe(result)
    assert result["object"]["__type__"] == "PublicObject"

import json

import pytest

import tapedeck.engine.tape as tape


class RecorderDouble:
    """A deliberately broad recorder-shaped object for build_tape tests."""

    def __init__(
        self,
        *,
        timeline=None,
        mocked_modules=None,
        value_index=None,
        nested_schemas=None,
        hierarchical_bindings=None,
        capture_mode="value_capture",
        prefer_return_value=True,
    ):
        self.timeline = [] if timeline is None else timeline
        self.events = self.timeline
        self.mocked_modules = {} if mocked_modules is None else mocked_modules
        self.value_index = {} if value_index is None else value_index
        self.nested_schemas = {} if nested_schemas is None else nested_schemas
        self.hierarchical_bindings = (
            {} if hierarchical_bindings is None else hierarchical_bindings
        )
        self.capture_mode = capture_mode
        self.prefer_return_value = prefer_return_value
        self.metadata = {
            "capture_mode": capture_mode,
            "prefer_return_value": prefer_return_value,
        }
        self.capture_metadata = self.metadata


def minimal_tape(**overrides):
    result = {
        "session": {},
        "timeline": [],
        "mocked_modules": {},
        "metadata": {},
    }
    result.update(overrides)
    return result


def write_json(tmp_path, content, name="tape.json"):
