import json

import pytest

from tapedeck.engine import serialize


SECRET_CATEGORIES = (
    ("token", ("token", "TOKEN", "access_token", "TokenValue")),
    ("secret", ("secret", "SECRET", "client_secret", "SecretValue")),
    ("password", ("password", "PASSWORD", "db_password", "PasswordHash")),
    ("api_key", ("api_key", "API_KEY", "service_api_key", "Api_KeyValue")),
    ("apikey", ("apikey", "APIKEY", "serviceapikey", "ApiKeyValue")),
    (
        "authorization",
        ("authorization", "AUTHORIZATION", "proxy_authorization", "AuthorizationHeader"),
    ),
    ("credential", ("credential", "CREDENTIAL", "user_credential", "CredentialStore")),
    ("refresh", ("refresh", "REFRESH", "refresh_token", "RefreshValue")),
)


def redactor(environ=None, extra=()):
    return serialize.Redactor.from_environ(environ or {}, extra)


