import copy
import json
from types import SimpleNamespace

import pytest

from tapedeck.engine import tape


class RecorderDouble:
    """Duck-typed recorder exposing the common tape-builder recorder fields."""

    def __init__(
        self,
        *,
        timeline=None,
        mocked_modules=None,
        value_index=None,
        capture_mode="value_capture",
        prefer_return_value=True,
        nested_schemas=None,
        hierarchical_bindings=None,
    ):
        self.timeline = [] if timeline is None else timeline
        self.events = self.timeline
        self.interactions = self.timeline
        self.captured_events = self.timeline

        self.mocked_modules = {} if mocked_modules is None else mocked_modules
        self.mocked_methods = self.mocked_modules

        self.value_index = {} if value_index is None else value_index
        self.capture_mode = capture_mode
        self.prefer_return_value = prefer_return_value
        self.metadata = {
            "capture_mode": capture_mode,
            "prefer_return_value": prefer_return_value,
        }
        self.capture_metadata = self.metadata
        self.config = SimpleNamespace(
            capture_mode=capture_mode,
            prefer_return_value=prefer_return_value,
        )

        self.nested_schemas = {} if nested_schemas is None else nested_schemas
        self.hierarchical_bindings = (
            {} if hierarchical_bindings is None else hierarchical_bindings
        )


def session_meta():
    return {
        "sdk": "example-sdk",
        "captured_at": "2026-01-02T03:04:05Z",
        "duration_s": 1.25,
    }


def valid_tape(**overrides):
    result = {
        "session": session_meta(),
        "timeline": [],
        "mocked_modules": {},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
