import json

import pytest

import tapedeck.engine.serialize as serialize


def redactor(*secrets):
    return serialize.Redactor.from_environ({}, extra=secrets)


def snapshot(value, *secrets, depth=0, schemas=None):
    if schemas is None:
        schemas = {}
    return serialize.snapshot(value, redactor(*secrets), schemas, depth=depth)


def assert_json_safe(value):
    json.dumps(value)
    if isinstance(value, dict):
        assert all(isinstance(key, str) for key in value)
        for child in value.values():
            assert_json_safe(child)
    elif isinstance(value, list):
        for child in value:
            assert_json_safe(child)


@pytest.mark.parametrize(
    "name",
