    assert serialize.SECRET_KEY_RE.search(name)


def test_secret_key_pattern_does_not_match_ordinary_name():
    assert serialize.SECRET_KEY_RE.search("username") is None


def test_redactor_collects_only_secret_named_environment_values_and_extras():
    value = serialize.Redactor.from_environ(
        {
            "API_TOKEN": "token-value",
