            "USERNAME": "alice",
            "refreshToken": "refresh-value",
            "clientCredential": "credential-value",
        },
        extra=["externally-supplied-secret"],
    ).scrub(
        "token-value password-value alice refresh-value credential-value "
        "externally-supplied-secret"
    )

    for secret in (
        "token-value",
        "password-value",
        "refresh-value",
        "credential-value",
        "externally-supplied-secret",
    ):
        assert secret not in value
    assert "alice" in value


