        "abcdef",
        "a.b[secret](x)?",
    ).scrub(
        "repeated-secret, repeated-secret; first-secret/second-secret; "
        "credential=abcdef; prefix a.b[secret](x)? suffix"
    )

    for secret in (
        "repeated-secret",
        "first-secret",
        "second-secret",
        "abcdef",
        "a.b[secret](x)?",
    ):
        assert secret not in value
    # Replacing abc before abcdef would leave this suffix visible.
    assert "def" not in value


