    assert_json_safe(at_limit)
    assert at_limit != nested

    deeply_nested = "leaf"
    for _ in range(200):
        deeply_nested = [deeply_nested]
    result = snapshot(deeply_nested)
    assert_json_safe(result)

    cursor = result
    observed_depth = 0
    while isinstance(cursor, list) and len(cursor) == 1:
        observed_depth += 1
        cursor = cursor[0]
    assert observed_depth < 200


