import json

import pytest

from tapedeck.engine import tape


class _Config:
    def __init__(self, capture_mode="value_capture", prefer_return_value=True):
        self.capture_mode = capture_mode
        self.prefer_return_value = prefer_return_value


class RecorderDouble:
    """A deliberately broad recorder-shaped object for build_tape contract tests."""

    def __init__(
        self,
        timeline=None,
        mocked_modules=None,
        value_index=None,
        nested_schemas=None,
        hierarchical_bindings=None,
    ):
        self.timeline = [] if timeline is None else timeline
        self.events = self.timeline
        self.records = self.timeline
        self.calls = self.timeline
        self._timeline = self.timeline

        self.mocked_modules = {} if mocked_modules is None else mocked_modules
        self._mocked_modules = self.mocked_modules

        self.value_index = {} if value_index is None else value_index
        self._value_index = self.value_index

        self.nested_schemas = {} if nested_schemas is None else nested_schemas
        self._nested_schemas = self.nested_schemas

        self.hierarchical_bindings = (
            {} if hierarchical_bindings is None else hierarchical_bindings
        )
        self._hierarchical_bindings = self.hierarchical_bindings

        self.capture_mode = "value_capture"
        self.prefer_return_value = True
        self.config = _Config()
        self.metadata = {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        }

    def get_timeline(self):
        return self.timeline

    def get_events(self):
        return self.timeline

    def get_mocked_modules(self):
        return self.mocked_modules

    def get_value_index(self):
        return self.value_index

    def get_nested_schemas(self):
        return self.nested_schemas

    def get_hierarchical_bindings(self):
        return self.hierarchical_bindings

    def get_metadata(self):
        return self.metadata


def valid_tape(**overrides):
    result = {
        "session": {
            "sdk": "test-sdk",
            "captured_at": "2026-01-02T03:04:05Z",
            "duration_s": 1.25,
        },
        "timeline": [],
        "mocked_modules": {},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
    }
    result.update(overrides)
    return result


def write_json_tape(path, content):
    path.write_text(json.dumps(content), encoding="utf-8")
    return str(path)


