        (0.0, 0.0),
        (-2.5, -2.5),
        (3.14159, 3.14159),
        ("", ""),
        ("null", "null"),
        ("true", "true"),
        ("false", "false"),
        ("0", "0"),
        ("[]", "[]"),
    ],
)
