import copy
import json

import pytest

from tapedeck.engine import tape


class RecorderLike:
    def __init__(
        self,
        *,
        timeline=None,
        mocked_modules=None,
        value_index=None,
        nested_schemas=None,
        hierarchical_bindings=None,
    ):
        self.timeline = [] if timeline is None else timeline
        self.mocked_modules = {} if mocked_modules is None else mocked_modules
        self.value_index = {} if value_index is None else value_index
        self.nested_schemas = {} if nested_schemas is None else nested_schemas
        self.hierarchical_bindings = (
            {} if hierarchical_bindings is None else hierarchical_bindings
        )


def valid_tape(**overrides):
    result = {
        "session": {
            "sdk": "example-sdk",
            "captured_at": "2026-01-02T03:04:05Z",
            "duration_s": 1.25,
        },
        "timeline": [],
        "mocked_modules": {},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
    }
    result.update(overrides)
    return result


def assert_invalid(value):
    with pytest.raises(Exception):
        tape.validate_tape(value)


def write_json(path, value):
    path.write_text(json.dumps(value), encoding="utf-8")
    return str(path)


def test_required_keys_constant_and_build_tape_required_sections():
    recorder = RecorderLike()
    built = tape.build_tape(recorder, {})

    assert tape.REQUIRED_KEYS == ("session", "timeline", "mocked_modules", "metadata")
    assert set(tape.REQUIRED_KEYS).issubset(built)
    assert "value_index" in built


def test_build_tape_uses_supplied_session_metadata_including_empty_mapping():
    metadata = {
        "sdk": "sdk-name",
