import json

import pytest

from tapedeck.engine import serialize


def make_redactor(environ=None, extra=()):
    return serialize.Redactor.from_environ(environ or {}, extra=extra)


def snap(value, redactor=None, schemas=None, depth=0):
    return serialize.snapshot(
        value,
        redactor or make_redactor(),
        schemas if schemas is not None else {},
        depth,
    )


@pytest.mark.parametrize(
    "term",
    [
        "token",
        "secret",
        "password",
        "api_key",
        "apikey",
        "authorization",
        "credential",
        "refresh",
    ],
)
def test_secret_key_pattern_matches_every_documented_term_case_insensitively(term):
    assert serialize.SECRET_KEY_RE.search(f"prefix_{term.upper()}_suffix")
    assert serialize.SECRET_KEY_RE.search(f"prefix_{term.title()}_suffix")


@pytest.mark.parametrize(
    "key",
    ["access_token", "myPasswordValue", "x-api_key-y", "clientapikeyvalue"],
)
def test_secret_key_pattern_matches_substrings(key):
    assert serialize.SECRET_KEY_RE.search(key)


@pytest.mark.parametrize("key", ["username", "host", "colour", "session", "name", "count"])
def test_secret_key_pattern_does_not_match_unrelated_keys(key):
    assert serialize.SECRET_KEY_RE.search(key) is None


def test_redactor_collects_secret_named_environment_values_and_extras():
    redactor = make_redactor(
        {
            "API_TOKEN": "token-value",
            "PASSWORD": "password-value",
            "HOST": "example.test",
            "USERNAME": "alice",
            "refreshToken": "refresh-value",
            "authorization": "authorization-value",
        },
        extra=["manual-secret", "another-secret"],
    )

    text = (
        "token-value password-value refresh-value authorization-value "
        "manual-secret another-secret example.test alice"
    )
    scrubbed = redactor.scrub(text)

    for secret in (
        "token-value",
        "password-value",
        "refresh-value",
        "authorization-value",
        "manual-secret",
        "another-secret",
    ):
        assert secret not in scrubbed
    assert "example.test" in scrubbed
    assert "alice" in scrubbed


def test_redactor_accepts_iterator_and_combines_environment_and_extra_secrets():
    extras = (value for value in ("first-extra-secret", "second-extra-secret"))
    redactor = make_redactor({"API_KEY": "environment-secret"}, extras)

    scrubbed = redactor.scrub(
        "environment-secret / first-extra-secret / second-extra-secret"
    )

    for secret in (
        "environment-secret",
        "first-extra-secret",
        "second-extra-secret",
    ):
        assert secret not in scrubbed


def test_redactor_scrubs_exact_embedded_repeated_and_multiple_secret_values():
    redactor = make_redactor(
        extra=["credential-value", "repeat-secret", "first-secret", "second-secret"]
    )

    exact = redactor.scrub("credential-value")
    embedded = redactor.scrub("Bearer credential-value for request")
    repeated = redactor.scrub("repeat-secret/repeat-secret")
    multiple = redactor.scrub("first-secret and second-secret")

    assert "credential-value" not in exact
    assert exact != "credential-value"
    assert "credential-value" not in embedded
    assert embedded.startswith("Bearer ")
    assert embedded.endswith(" for request")
    assert "repeat-secret" not in repeated
    assert "first-secret" not in multiple
    assert "second-secret" not in multiple


def test_redactor_handles_overlapping_secret_values_without_leaking_longer_value():
    redactor = make_redactor(extra=["abc", "abcdef"])

    scrubbed = redactor.scrub("value=abcdef")

    assert "abcdef" not in scrubbed
    assert "abc" not in scrubbed
    # A partial replacement of only "abc" would leave part of the longer credential.
    assert not scrubbed.endswith("def")


