def test_snapshot_nested_values_remain_json_safe_and_never_leak_environment_credential():
    class Widget:
        def __init__(self):
            self.message = "environment-credential"
            self.child = {"values": ["safe", "prefix-environment-credential-suffix"]}
            self._private = "environment-credential"

    redactor = make_redactor({"API_TOKEN": "environment-credential"})
    schemas = {}
    result = snap({"widget": Widget(), "message": "using environment-credential now"}, redactor, schemas)

